-- ─────────────────────────────────────────────────────────────────
-- 0010 — Locales para comprar la previa (kioscos, vinotecas, bebidas)
--
-- Qué resuelve: antes de una previa hay que ir a comprar. El mapa ya sabe
-- dónde es la juntada; ahora también dónde está el kiosco abierto más cerca.
--
-- Por qué en la base y no llamando a OpenStreetMap desde el teléfono:
-- la Overpass API es gratis pero inestable — en las pruebas devolvió
-- "server too busy" en 3 de cada 5 llamadas. Un local no se mueve, así que
-- el dato se importa una vez y se sirve desde acá, igual que `zones`.
--
-- Sobre los horarios: OSM tiene `opening_hours` cargado en muy pocos locales
-- argentinos (1,7% en La Plata, 14% en Bariloche). El campo se guarda tal
-- cual viene y puede ser NULL. La UI muestra "Horario no cargado" cuando
-- falta: NUNCA se inventa un horario por tipo de local, porque mandaría
-- gente a un negocio cerrado.
--
-- Datos de OpenStreetMap, licencia ODbL. La atribución ya está en el mapa.
--
-- El seed lo genera `npm run gen:shops` desde la caché de `fetch-shops.mjs`.
-- No se edita el bloque generado a mano.
-- ─────────────────────────────────────────────────────────────────

create table if not exists public.shops (
  -- Identidad de OSM: un local es (tipo de elemento, id). Es la clave natural
  -- y hace que re-importar sea idempotente.
  osm_type      text not null check (osm_type in ('node', 'way', 'relation')),
  osm_id        bigint not null,
  name          text not null,
  -- kiosco | vinoteca | bebidas | autoservicio | supermercado
  kind          text not null,
  lat           double precision not null,
  lng           double precision not null,
  -- Crudo de OSM ("Mo-Sa 08:00-22:00", "24/7"). NULL = no hay dato.
  opening_hours text,
  primary key (osm_type, osm_id)
);

-- El mapa siempre consulta por recuadro visible.
create index if not exists shops_bbox_idx on public.shops (lat, lng);

alter table public.shops enable row level security;

-- Catálogo público de comercios: no hay nada privado acá, pero se lee sólo
-- con sesión, igual que el resto del mapa.
drop policy if exists shops_select on public.shops;
create policy shops_select on public.shops for select to authenticated using (true);

-- ───────────────────── RPC: locales del recuadro ─────────────────────

create or replace function public.shops_in_bbox(
  p_min_lat double precision,
  p_min_lng double precision,
  p_max_lat double precision,
  p_max_lng double precision,
  p_limit int default 60
)
returns table (
  osm_type text, osm_id bigint, name text, kind text,
  lat double precision, lng double precision, opening_hours text
)
language sql security definer stable set search_path = public as $$
  select s.osm_type, s.osm_id, s.name, s.kind, s.lat, s.lng, s.opening_hours
  from public.shops s
  where s.lat between p_min_lat and p_max_lat
    and s.lng between p_min_lng and p_max_lng
  -- Del centro de la pantalla hacia afuera. Con `limit`, ordenar por nombre
  -- devolvía 60 locales desparramados por todo el recuadro y dejaba pelado
  -- justo el lugar que el usuario está mirando. No hace falta haversine para
  -- ordenar: dentro de un recuadro de ciudad, la distancia al cuadrado en
  -- grados (corregida por la latitud) ordena igual y es una cuenta sola.
  order by
    ((s.lat - (p_min_lat + p_max_lat) / 2) * (s.lat - (p_min_lat + p_max_lat) / 2)) +
    ((s.lng - (p_min_lng + p_max_lng) / 2) * (s.lng - (p_min_lng + p_max_lng) / 2) *
     cos(radians((p_min_lat + p_max_lat) / 2)) * cos(radians((p_min_lat + p_max_lat) / 2)))
  limit greatest(1, least(coalesce(p_limit, 60), 200));
$$;

revoke all on function public.shops_in_bbox(
  double precision, double precision, double precision, double precision, int
) from public, anon;
grant execute on function public.shops_in_bbox(
  double precision, double precision, double precision, double precision, int
) to authenticated;

